def magic_dictionary_search(dictionary, queries):
    root = {'children': {}, 'is_end': False}

    for word in dictionary:
        node = root
        for ch in word:
            node = node['children'].setdefault(ch, {'children': {}, 'is_end': False})
        node['is_end'] = True

    def dfs(node, word, i, mismatches_used):
        if i == len(word):
            return mismatches_used == 1 and node['is_end']
        ch = word[i]
        for child_ch, child in node['children'].items():
            if child_ch == ch:
                if dfs(child, word, i + 1, mismatches_used):
                    return True
            elif mismatches_used == 0:
                if dfs(child, word, i + 1, 1):
                    return True
        return False

    return [dfs(root, q, 0, 0) for q in queries]

